ClearAll["Global`*"];
sig=DiagonalMatrix[{-s,-s,2s}]; piM=DiagonalMatrix[{-dm/3,-dm/3,2dm/3}]; piR=DiagonalMatrix[{-dr/3,-dr/3,2dr/3}]; fro[x_]:=Tr[Transpose[x].x]; contractions={fro[sig],fro[piM],Tr[sig.piM],fro[piM+piR]};
edot=-c^2 ((h-s)qt2/ap^2+(h+2s)qz2/az^2)/ee; pp=c^2 qt2/(2 ap^2 ee); pz=c^2 qz2/(az^2 ee); pbar=(2pp+pz)/3; kernelEnergyIdentity=FullSimplify[edot+3h pbar+2s(pz-pp)];
hdot=-kt(rho+p)/2-3s^2; sdot=-3h s+kt(dm+dr)/3; rhodot=-3h(rho+p)-2s(dm+dr); constraintDerivative=Expand[6h hdot-kt rhodot-6s sdot];
normalizedShear=FullSimplify[Sqrt[3](sdot/h^2-s hdot/h^3)-((q-2)Sqrt[3]s/h+kt(dm+dr)/(Sqrt[3]h^2))/.q->-1-hdot/h^2];
p2=(3mu^2-1)/2; angular={Integrate[1+A p2,{mu,-1,1}]/2,Integrate[p2(1+A p2),{mu,-1,1}]/2}; positivity=Reduce[ForAll[mu,-1<=mu<=1,1+A p2>=0],A,Reals];
<|"tensor_contractions"->contractions,"single_momentum_energy_identity"->kernelEnergyIdentity,"constraint_derivative"->constraintDerivative,"normalized_shear_residual"->normalizedShear,"P2_angular_averages"->angular,"P2_positivity"->positivity|>
